import React from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { useToast } from '../../../contexts/ToastContext';

const ShareModal = ({ isOpen, onClose, opportunity }) => {
  const { addToast } = useToast();
  if (!isOpen) return null;

  const shareUrl = window.location?.href;
  const shareText = `Check out this amazing opportunity: ${opportunity?.title}`;

  const shareOptions = [
    {
      name: 'WhatsApp',
      icon: 'MessageCircle',
      color: 'bg-[#25D366]',
      action: () => {
        window.open(
          `https://wa.me/?text=${encodeURIComponent(shareText + ' ' + shareUrl)}`,
          '_blank'
        );
      }
    },
    {
      name: 'Facebook',
      icon: 'Facebook',
      color: 'bg-[#1877F2]',
      action: () => {
        window.open(
          `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}`,
          '_blank'
        );
      }
    },
    {
      name: 'Twitter',
      icon: 'Twitter',
      color: 'bg-[#1DA1F2]',
      action: () => {
        window.open(
          `https://twitter.com/intent/tweet?text=${encodeURIComponent(shareText)}&url=${encodeURIComponent(shareUrl)}`,
          '_blank'
        );
      }
    },
    {
      name: 'LinkedIn',
      icon: 'Linkedin',
      color: 'bg-[#0A66C2]',
      action: () => {
        window.open(
          `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(shareUrl)}`,
          '_blank'
        );
      }
    },
    {
      name: 'Email',
      icon: 'Mail',
      color: 'bg-muted',
      action: () => {
        window.location.href = `mailto:?subject=${encodeURIComponent(opportunity?.title)}&body=${encodeURIComponent(shareText + '\n\n' + shareUrl)}`;
      }
    },
    {
      name: 'Copy Link',
      icon: 'Link',
      color: 'bg-muted',
      action: () => {
        navigator.clipboard?.writeText(shareUrl);
        addToast('Link copied to clipboard!', 'success');
      }
    }
  ];

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-background/80 backdrop-blur-sm">
      <div className="bg-card rounded-2xl shadow-modal w-full max-w-md max-h-[90vh] overflow-y-auto">
        <div className="sticky top-0 bg-card border-b border-border p-4 md:p-6 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center">
              <Icon name="Share2" size={20} className="text-primary" />
            </div>
            <h2 className="text-lg md:text-xl font-bold text-primary">Share Opportunity</h2>
          </div>
          <button
            onClick={onClose}
            className="w-8 h-8 rounded-lg hover:bg-muted flex items-center justify-center transition-colors duration-300"
          >
            <Icon name="X" size={20} />
          </button>
        </div>

        <div className="p-4 md:p-6">
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 md:gap-4">
            {shareOptions?.map((option) => (
              <button
                key={option?.name}
                onClick={option?.action}
                className="flex flex-col items-center gap-2 p-4 rounded-xl border-2 border-border hover:border-secondary/50 transition-all duration-300 hover:scale-105"
              >
                <div className={`w-12 h-12 rounded-full ${option?.color} flex items-center justify-center text-white`}>
                  <Icon name={option?.icon} size={20} />
                </div>
                <span className="text-xs md:text-sm font-medium text-foreground">{option?.name}</span>
              </button>
            ))}
          </div>

          <div className="mt-6 p-4 rounded-xl bg-muted">
            <p className="text-xs md:text-sm text-muted-foreground mb-2">Share Link</p>
            <div className="flex items-center gap-2">
              <input
                type="text"
                value={shareUrl}
                readOnly
                className="flex-1 px-3 py-2 text-xs md:text-sm bg-background border border-border rounded-lg text-foreground"
              />
              <Button
                variant="outline"
                size="sm"
                iconName="Copy"
                onClick={() => {
                  navigator.clipboard?.writeText(shareUrl);
                  addToast('Link copied!', 'success');
                }}
              >
                Copy
              </Button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ShareModal;