import React from 'react';
import Image from '../../../components/AppImage';
import Icon from '../../../components/AppIcon';
import SuccessStoryModal from './SuccessStoryModal';

const SuccessStories = ({ opportunityTitle, stories = [] }) => {
  const [isModalOpen, setIsModalOpen] = React.useState(false);
  return (
    <div className="bg-card rounded-2xl p-6 md:p-8 shadow-card">
      <div className="flex items-center gap-3 mb-6">
        <div className="w-10 h-10 md:w-12 md:h-12 rounded-lg bg-success/10 flex items-center justify-center">
          <Icon name="Trophy" size={20} className="text-success" />
        </div>
        <div className="flex-1">
          <h2 className="text-xl md:text-2xl font-bold text-primary">Success Stories</h2>
          <p className="text-xs md:text-sm text-muted-foreground mt-1">
            {stories.length > 0 ? `Real impact from ${stories.length} community members` : "Join our community of achievers"}
          </p>
        </div>
      </div>

      {stories.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6 mb-8">
          {stories.map((story, idx) => (
            <div
              key={idx}
              className="bg-background rounded-xl p-4 md:p-6 border-2 border-border hover:border-secondary/50 transition-all duration-300"
            >
              <div className="flex items-center gap-3 mb-4">
                <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold text-xs uppercase">
                  {story.name?.[0]}
                </div>
                <div className="flex-1 min-w-0">
                  <h4 className="font-bold text-xs text-primary truncate">{story.name}</h4>
                  <div className="flex items-center gap-1">
                    {[1, 2, 3, 4, 5].map((star) => (
                      <Icon
                        key={star}
                        name="Star"
                        size={8}
                        fill={star <= story.rating ? "currentColor" : "none"}
                        className={star <= story.rating ? "text-orange-400" : "text-muted-foreground/20"}
                      />
                    ))}
                  </div>
                </div>
              </div>
              <p className="text-xs text-muted-foreground leading-relaxed italic line-clamp-4">
                "{story.story}"
              </p>
            </div>
          ))}
        </div>
      )}

      <div className="p-5 md:p-6 rounded-2xl bg-gradient-to-br from-success/5 to-brand-blue/5 border border-success/10">
        <div className="flex items-start gap-4">
          <div className="w-10 h-10 rounded-full bg-brand-blue/10 flex items-center justify-center flex-shrink-0 mt-1">
            <Icon name="MessageCircle" size={20} className="text-brand-blue" />
          </div>
          <div>
            <p className="text-base md:text-lg font-bold text-primary mb-2">
              Share Your Success Story
            </p>
            <p className="text-sm md:text-base text-foreground/70 leading-relaxed">
              Received this opportunity? Help others by sharing your experience with the LUC community.
            </p>
            <button
              onClick={() => setIsModalOpen(true)}
              className="mt-4 text-sm font-black text-secondary hover:underline flex items-center gap-1 uppercase tracking-wider italic"
            >
              SHARE MY STORY <Icon name="ArrowRight" size={14} />
            </button>
          </div>
        </div>
      </div>

      <SuccessStoryModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        opportunityTitle={opportunityTitle}
      />
    </div>
  );
};

export default SuccessStories;