import React, { useState } from 'react';
import { useSelector } from 'react-redux';
import Modal from '../../../components/ui/Modal';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import Input from '../../../components/ui/Input';
import { useToast } from '../../../contexts/ToastContext';
import { supabaseService } from '../../../services/supabaseService';

const SuccessStoryModal = ({ isOpen, onClose, opportunityTitle }) => {
    const { user } = useSelector((state) => state.auth);
    const [loading, setLoading] = useState(false);
    const [name, setName] = useState(user?.name || '');
    const [story, setStory] = useState('');
    const [rating, setRating] = useState(5);
    const { addToast } = useToast();

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);

        try {
            // Using the common contact submission for now as success story
            // Perfect for LUC team to review and then add manually or auto-publish
            await supabaseService.submitContactMessage({
                name: name,
                email: user?.email || 'success-story@lucopportunities.com',
                subject: `Success Story: ${opportunityTitle}`,
                message: `Rating: ${rating}/5\n\nStory:\n${story}`,
                inquiry_type: 'success_story',
                agreed_to_terms: true
            });

            addToast('Your story has been submitted! Our team will review it soon.', 'success');
            onClose();
            // Reset form
            setName('');
            setStory('');
            setRating(5);
        } catch (error) {
            console.error('Error submitting story:', error);
            addToast('Failed to submit story. Please try again.', 'error');
        } finally {
            setLoading(false);
        }
    };

    return (
        <Modal
            isOpen={isOpen}
            onClose={onClose}
            title="Share Your Success"
            size="md"
        >
            <form onSubmit={handleSubmit} className="space-y-6">
                <div className="text-center mb-6">
                    <div className="w-16 h-16 bg-success/10 rounded-full flex items-center justify-center mx-auto mb-4">
                        <Icon name="Trophy" size={32} className="text-success" />
                    </div>
                    <p className="text-sm text-muted-foreground">
                        Tell us how receiving this opportunity changed your journey.
                    </p>
                </div>

                <div className="space-y-4">
                    <div>
                        <label className="block text-sm font-bold text-primary mb-2 uppercase tracking-tighter italic">Your Full Name</label>
                        <Input
                            required
                            placeholder="How should we credit you?"
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-bold text-primary mb-2 uppercase tracking-tighter italic">Experience Rating</label>
                        <div className="flex gap-2">
                            {[1, 2, 3, 4, 5].map((star) => (
                                <button
                                    key={star}
                                    type="button"
                                    onClick={() => setRating(star)}
                                    className="focus:outline-none transition-transform hover:scale-110"
                                >
                                    <Icon
                                        name="Star"
                                        size={28}
                                        fill={star <= rating ? "var(--color-accent)" : "none"}
                                        className={star <= rating ? "text-accent" : "text-muted-foreground"}
                                    />
                                </button>
                            ))}
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-bold text-primary mb-2 uppercase tracking-tighter italic">Your Story</label>
                        <textarea
                            required
                            placeholder="Tell the community about your win..."
                            className="w-full h-32 p-4 bg-background dark:bg-muted/10 border-2 border-border text-foreground rounded-2xl focus:border-secondary transition-all outline-none resize-none text-sm placeholder:text-muted-foreground"
                            value={story}
                            onChange={(e) => setStory(e.target.value)}
                        />
                    </div>
                </div>

                <div className="pt-2">
                    <Button
                        fullWidth
                        disabled={loading}
                        iconName={loading ? "Loader2" : "Send"}
                        className={loading ? "animate-pulse" : ""}
                        type="submit"
                    >
                        {loading ? "Submitting..." : "Submit My Story"}
                    </Button>
                </div>
            </form>
        </Modal>
    );
};

export default SuccessStoryModal;
