import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { fetchAllContent, toggleSaveOpportunityAsync, trackViewAsync, trackApplicantAsync, toggleLikeOpportunityAsync, fetchLikedOpportunitiesAsync, fetchSavedOpportunitiesAsync } from '../../store/contentSlice';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import Button from '../../components/ui/Button';
import Icon from '../../components/AppIcon';
import OpportunityHero from './components/OpportunityHero';
import KeyInformation from './components/KeyInformation';
import DetailedDescription from './components/DetailedDescription';
import SuccessStories from './components/SuccessStories';
import RelatedOpportunities from './components/RelatedOpportunities';
import ApplicationChecklist from './components/ApplicationChecklist';
import ShareModal from './components/ShareModal';
import StickyActionBar from './components/StickyActionBar';
import Modal from '../../components/ui/Modal';
import { useToast } from '../../contexts/ToastContext';
import { cn } from '../../utils/cn';

const OpportunityDetail = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { addToast } = useToast();
  const { id } = useParams();
  const { user } = useSelector((state) => state.auth);
  const { allOpportunities, idMap, likedOpportunities, isLoading } = useSelector((state) => state.content);

  const isSaved = !!idMap[id];
  // Find the specific opportunity
  // Handle both string (URL) and number (Redux) IDs
  const opportunity = allOpportunities.find(o => String(o.id) === String(id));

  const isLiked = likedOpportunities?.includes(opportunity?.id);
  const [isShareModalOpen, setIsShareModalOpen] = useState(false);
  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);
  const [showStickyBar, setShowStickyBar] = useState(false);

  // Use 'opportunity.daysLeft <= 0' as the source of truth for 'isExpired'
  const isExpired = opportunity?.daysLeft !== null && opportunity?.daysLeft <= 0;

  // Derive related opportunities
  const relatedOpportunities = allOpportunities
    .filter(o => o.category === opportunity?.category && String(o.id) !== String(id))
    .slice(0, 3);

  // Map processList to checklist format
  const applicationChecklist = opportunity?.processList?.map((step, index) => ({
    id: index,
    title: step,
    description: '', // You could add rich descriptions in the future
    tip: ''
  })) || [];



  useEffect(() => {
    if (id) {
      dispatch(trackViewAsync(id));
    }
    if (user?.id) {
      dispatch(fetchLikedOpportunitiesAsync(user.id));
      dispatch(fetchSavedOpportunitiesAsync(user.id));
    }
  }, [id, user?.id, dispatch]);

  useEffect(() => {
    const handleScroll = () => {
      setShowStickyBar(window.scrollY > 600);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleSave = () => {
    if (isExpired) return;
    if (!user) {
      setIsLoginModalOpen(true);
      return;
    }
    dispatch(toggleSaveOpportunityAsync({ userId: user.id, opportunityId: opportunity.id }));
    addToast(isSaved ? "Removed from saved" : "Opportunity saved!", "success");
  };

  const handleApply = () => {
    if (isExpired) return;
    dispatch(trackApplicantAsync(opportunity.id));
    if (opportunity.applicationLink) {
      window.open(opportunity.applicationLink, '_blank');
    } else {
      addToast('Application successful! (Demo Mode)', 'success');
    }
  };

  const handleLike = () => {
    if (isExpired) return;
    if (!user) {
      setIsLoginModalOpen(true);
      return;
    }
    dispatch(toggleLikeOpportunityAsync({ userId: user.id, opportunityId: opportunity.id }));
  };

  const handleShare = () => {
    setIsShareModalOpen(true);
  };

  const handleCloseShareModal = () => {
    setIsShareModalOpen(false);
  };

  if (!opportunity) {
    return (
      <div className="min-h-screen bg-background flex flex-col">
        <Header />
        <main className="flex-1 flex items-center justify-center">
          <div className="text-center">
            <h2 className="text-2xl font-bold mb-2">Opportunity Not Found</h2>
            <p className="text-muted-foreground mb-4">The opportunity you are looking for does not exist or has been removed.</p>
            <button onClick={() => navigate('/opportunity-discovery')} className="text-primary hover:underline">
              Back to Opportunities
            </button>
          </div>
        </main>
        <Footer />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <Header />
      <main className="flex-1">
        <nav className="bg-card border-b border-border">
          <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-3 md:py-4">
            <div className="flex items-center gap-2 text-xs md:text-sm">
              <button
                onClick={() => navigate('/homepage')}
                className="text-muted-foreground hover:text-primary transition-colors duration-300"
              >
                Home
              </button>
              <Icon name="ChevronRight" size={14} className="text-muted-foreground" />
              <button
                onClick={() => navigate('/opportunity-discovery')}
                className="text-muted-foreground hover:text-primary transition-colors duration-300"
              >
                Opportunities
              </button>
              <Icon name="ChevronRight" size={14} className="text-muted-foreground" />
              <span className="text-primary font-medium truncate">
                {opportunity?.title}
              </span>
            </div>
          </div>
        </nav>

        <OpportunityHero
          opportunity={opportunity}
          onSave={handleSave}
          onShare={handleShare}
          onApply={handleApply}
          onLike={handleLike}
          isSaved={isSaved}
          isLiked={isLiked}
        />

        <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-8 md:py-12 lg:py-16">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 md:gap-8">
            <div className="lg:col-span-2 space-y-6 md:space-y-8">
              <DetailedDescription opportunity={opportunity} />
              <SuccessStories
                opportunityTitle={opportunity?.title}
                stories={opportunity?.successStories || []}
              />
            </div>

            <div className="space-y-6 md:space-y-8">
              <KeyInformation opportunity={opportunity} />
              {applicationChecklist.length > 0 && (
                <ApplicationChecklist checklist={applicationChecklist} />
              )}
            </div>
          </div>

          <div className="mt-8 md:mt-12 lg:mt-16">
            <RelatedOpportunities opportunities={relatedOpportunities} />
          </div>
        </div>

        <div className="bg-gradient-to-br from-primary/5 via-secondary/5 to-accent/5 py-8 md:py-12 lg:py-16">
          <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
            <div className="bg-card rounded-2xl p-6 md:p-8 lg:p-12 shadow-elevated text-center">
              <div className="w-16 h-16 md:w-20 md:h-20 rounded-full bg-gradient-to-br from-brand-blue to-brand-purple flex items-center justify-center mx-auto mb-4 md:mb-6">
                <Icon name="Rocket" size={32} className="text-white" />
              </div>
              <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold text-primary mb-3 md:mb-4">
                Ready to Apply?
              </h2>
              <p className="text-sm md:text-base lg:text-lg text-foreground/80 mb-6 md:mb-8 max-w-2xl mx-auto">
                Don't miss this life-changing opportunity. Join thousands of successful candidates who have transformed their careers.
              </p>
              <div className="flex flex-col sm:flex-row gap-3 justify-center items-center">
                <button
                  onClick={isExpired ? null : handleApply}
                  disabled={isExpired}
                  className={cn(
                    "cta-primary w-full sm:w-auto text-center py-2.5 flex items-center justify-center gap-2",
                    isExpired && "bg-gray-400 hover:bg-gray-400 cursor-not-allowed opacity-70"
                  )}
                >
                  {isExpired && <Icon name="Lock" size={18} />}
                  {isExpired ? "Application Closed" : "Start Application"}
                </button>
                <button
                  onClick={() => navigate('/contact')}
                  className="cta-secondary w-full sm:w-auto text-center py-2"
                >
                  Contact Support
                </button>
              </div>
            </div>
          </div>
        </div>
      </main>
      <Footer />
      <ShareModal
        isOpen={isShareModalOpen}
        onClose={handleCloseShareModal}
        opportunity={opportunity}
      />
      <StickyActionBar
        opportunity={opportunity}
        onSave={handleSave}
        onShare={handleShare}
        onApply={handleApply}
        isSaved={isSaved}
        isVisible={showStickyBar}
      />

      <Modal
        isOpen={isLoginModalOpen}
        onClose={() => setIsLoginModalOpen(false)}
        title="Authentication Required"
        size="sm"
        footer={
          <div className="flex w-full gap-3">
            <Button variant="ghost" fullWidth onClick={() => setIsLoginModalOpen(false)}>
              Maybe Later
            </Button>
            <Button variant="default" fullWidth onClick={() => navigate('/login')}>
              Login Now
            </Button>
          </div>
        }
      >
        <div className="text-center py-4">
          <div className="w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-4 text-primary">
            <Icon name="Lock" size={32} />
          </div>
          <p className="text-muted-foreground">
            Please sign in to your LUC Hub account to save opportunities and track your applications.
          </p>
        </div>
      </Modal>
    </div>
  );
};

export default OpportunityDetail;